// ================= AUTH =================
function renderAuth(){ var el=$("v-auth");
  el.innerHTML='<div class="authwrap"><div class="logo">EVO<span class="bar"></span></div><div class="eyebrow" style="text-align:center">Evolution</div><div class="card stack"><div class="field"><label for="a-email">Email</label><input type="text" id="a-email" inputmode="email" autocomplete="email"></div><div class="field"><label for="a-pass">Password</label><input type="password" id="a-pass" autocomplete="current-password"></div><div class="field" id="a-namewrap" hidden><label for="a-name">Your name</label><input type="text" id="a-name" autocomplete="name"></div><button class="btn big" id="a-in">Sign in</button><button class="btn quiet" id="a-up">Create account</button><div class="sub" id="a-msg" style="min-height:1.4em"></div></div>'+(SB?'':'<div class="sub" style="text-align:center">Offline. Connect once to sign in.</div>')+'</div>';
  var msg=el.querySelector("#a-msg");
  el.querySelector("#a-in").addEventListener("click",function(){ var e=el.querySelector("#a-email").value.trim(), p=el.querySelector("#a-pass").value; if(!e||!p){ msg.textContent="Email and password."; return; } msg.textContent="Signing in…"; SB.auth.signInWithPassword({email:e,password:p}).then(function(r){ if(r.error){ msg.textContent=r.error.message; return; } CU=r.data.user; cloudPull().then(function(){ cloudPush(); gate(); }); }); });
  el.querySelector("#a-up").addEventListener("click",function(){ var nw=el.querySelector("#a-namewrap"); if(nw.hidden){ nw.hidden=false; el.querySelector("#a-name").focus(); msg.textContent="Add your name, then tap Create account again."; return; } var e=el.querySelector("#a-email").value.trim(), p=el.querySelector("#a-pass").value, n=el.querySelector("#a-name").value.trim(); if(!e||p.length<6||!n){ msg.textContent="Email, a name, and a password of 6+ characters."; return; } msg.textContent="Creating…"; SB.auth.signUp({email:e,password:p}).then(function(r){ if(r.error){ msg.textContent=r.error.message; return; } if(!r.data.session){ msg.textContent="Account created but email confirmation is on. Turn it off in Supabase, then sign in."; return; } CU=r.data.user; S.pendingName=n; save(); gate(); }); });
}

// ================= SETUP =================
var SETUP=null;
function renderSetup(){ var first=!S.program; if(!SETUP){ SETUP= S.program?JSON.parse(JSON.stringify(S.program)):{template:"base",kit:[],wake:"05:10",name:S.pendingName||"",handle:""}; SETUP.name=SETUP.name||S.pendingName||""; SETUP.bedtime=S.bedtime; SETUP.testDate=S.testDate; SETUP.routineText=(S.routineItems||ROUTINE_DEF).join("\n"); SETUP.eveningText=(S.eveningItems||EVENING_DEF).join("\n"); }
  var P=SETUP; var el=$("v-setup");
  var h='<div class="card hi stack"><div><div class="eyebrow">'+(first?"Set up":"Program and kit")+'</div><h2>'+(first?"What are you training for?":"Change anything")+'</h2></div>';
  h+='<div class="field"><label for="su-name">Name (your crew sees this)</label><input type="text" id="su-name" value="'+esc(P.name)+'"></div>';
  h+='<div class="field"><label>Program</label><div class="chips">'+[["force","FORCE Prep"],["base","Base"],["strength","Strength"],["run","Run"]].map(function(x){return '<button class="chip '+(P.template===x[0]?"on":"")+'" data-tpl="'+x[0]+'">'+x[1]+'</button>';}).join("")+'</div><div class="sub">'+esc({force:"CAF entry test: sandbag work, test sims, test-day countdown.",base:"Get fit with what you've got. Strength, intervals, Saturday outdoors.",strength:"Four strength days, two cardio.",run:"Three runs, two strength days, Saturday outdoors."}[P.template])+' You can change every day of it afterwards in Plan.</div></div>';
  h+='<div class="field"><label>Kit · tap everything you have</label><div class="chips">'+KIT.map(function(k){return '<button class="chip '+(P.kit.indexOf(k[0])>=0?"on":"")+'" data-kit="'+k[0]+'">'+esc(k[1])+'</button>';}).join("")+'</div></div>';
  h+='<div class="grid2"><div class="field"><label for="su-wake">Wake time</label><input type="time" id="su-wake" value="'+esc(P.wake)+'"></div><div class="field"><label for="su-bed">Lights out</label><input type="time" id="su-bed" value="'+esc(P.bedtime)+'"></div>'+(P.template==="force"?'<div class="field"><label for="su-test">Test date</label><input type="date" id="su-test" value="'+esc(P.testDate)+'"></div>':'')+'</div>';
  h+='<details><summary>Morning routine and night-before lists</summary><div class="body"><div class="field"><label for="su-rt">Morning routine · one per line · {wake} = your wake time</label><textarea id="su-rt">'+esc(P.routineText)+'</textarea></div><div class="field"><label for="su-ev">Night before · one per line</label><textarea id="su-ev">'+esc(P.eveningText)+'</textarea></div></div></details>';
  h+='<button class="btn big" id="su-save">'+(first?"Start":"Save")+'</button>'+(first?'':'<button class="btn quiet" id="su-cancel">Cancel</button>')+'</div>';
  el.innerHTML=h;
  function keep(){ var n=el.querySelector("#su-name"); if(n) P.name=n.value; var w=el.querySelector("#su-wake"); if(w&&w.value) P.wake=w.value; var bd=el.querySelector("#su-bed"); if(bd&&bd.value) P.bedtime=bd.value; var td=el.querySelector("#su-test"); if(td&&td.value) P.testDate=td.value; var rt=el.querySelector("#su-rt"); if(rt) P.routineText=rt.value; var ev=el.querySelector("#su-ev"); if(ev) P.eveningText=ev.value; }
  el.querySelectorAll("[data-tpl]").forEach(function(b){ b.addEventListener("click",function(){ keep(); P.template=b.dataset.tpl; P._tplChanged=true; renderSetup(); }); });
  el.querySelectorAll("[data-kit]").forEach(function(b){ b.addEventListener("click",function(){ var k=b.dataset.kit; var i=P.kit.indexOf(k); if(i>=0) P.kit.splice(i,1); else P.kit.push(k); b.classList.toggle("on"); }); });
  var c=el.querySelector("#su-cancel"); if(c) c.addEventListener("click",function(){ SETUP=null; back(); });
  el.querySelector("#su-save").addEventListener("click",function(){ P.name=el.querySelector("#su-name").value.trim()||P.name; P.wake=el.querySelector("#su-wake").value||"05:10"; S.bedtime=el.querySelector("#su-bed").value||S.bedtime; var td=el.querySelector("#su-test"); if(td&&td.value) S.testDate=td.value;
    var rt=el.querySelector("#su-rt").value.split("\n").map(function(x){return x.trim();}).filter(Boolean), ev=el.querySelector("#su-ev").value.split("\n").map(function(x){return x.trim();}).filter(Boolean); S.routineItems=rt.join("\n")===ROUTINE_DEF.join("\n")?null:rt; S.eveningItems=ev.join("\n")===EVENING_DEF.join("\n")?null:ev;
    var changed=first||P._tplChanged; ["bedtime","testDate","routineText","eveningText","_tplChanged"].forEach(function(k){ delete P[k]; }); if(!P.handle) P.handle=mkHandle(P.name);
    if(first) S.start=iso(mondayOf(today())); S.program=P; if(changed) S.plan=defaultPlan(P.template,P.kit); delete S.pendingName; SETUP=null; save(); toast(first?"Welcome. First evolution's on the Home tab.":"Saved"); show("today"); });
}
function mkHandle(n){ var b=(n||"evo").toLowerCase().replace(/[^a-z0-9]/g,"").slice(0,12)||"evo"; return b+Math.floor(100+Math.random()*900); }

// ================= HOME =================
function isEvening(){ return new Date().getHours()>=18; }
function sessionCard(t,k,p){ var dn=S.done[k]||{}; var adjKey=p.kind==="lift"?"lift":p.kind==="bike"?"bike":null; var adjV=adjKey?S.adj[adjKey]:0; var generated=(S.plan.days[t.getDay()]||{}).type!=="custom";
  var total=p.blocks.length, doneN=p.blocks.filter(function(b,i){return dn["b"+i];}).length; var pct=S.workouts[k]?100:total?Math.round(doneN/total*100):0; var secured=!!S.workouts[k]; var mainN=p.blocks.filter(function(b){return !b.warm&&!b.cool;}).length;
  var parts=p.title.split(" · ");
  var h='<section class="mission'+(secured?" secured":"")+'"><div class="topo"></div><div class="mhead"><div class="eyebrow">Evolution '+("00"+(secured?evoNumber()-1:evoNumber())).slice(-3)+' · '+(secured?"secured":"today")+'</div><h1 class="mtitle">'+esc(parts[0])+(parts[1]?'<small>'+esc(parts[1])+'</small>':'')+'</h1><div class="meta">'+(p.mins?'<span>'+p.mins+' min</span>':'')+(mainN?'<span>'+mainN+' exercises</span>':'')+'<span>'+esc(PHASES[phase(weekOf(t))-1].n)+'</span>'+(adjKey&&adjV!==0&&generated?'<span class="hl">'+(adjV>0?"+":"")+adjV+' adaptive</span>':'')+'</div><p class="msub">'+esc(p.sub)+'</p>';
  if(p.blocks.length&&p.kind!=="rest") h+='<div class="pbar"><i style="width:'+pct+'%"></i></div>';
  if(secured){ var wk=S.workouts[k]; h+='<div class="secline"><b>Secured</b> '+(wk.sec?Math.round(wk.sec/60)+' min · finished '+esc(wk.at||""):'')+' · streak <b>'+trainStreak()+'</b></div>';
    if(adjKey&&!S.feel[k]&&generated) h+='<div class="stack"><div class="eyebrow">How was it?</div><div class="rate"><button class="btn quiet" data-rate="1">Easy</button><button class="btn quiet" data-rate="2">Right</button><button class="btn quiet" data-rate="3">Too hard</button></div></div>';
    if(p.kind==="lift"&&!(S.pr.pushups||[]).some(function(x){return x.date===k;})) h+='<div class="row"><div class="field" style="flex:1"><label for="pu">Push-up max today</label><input type="number" id="pu" inputmode="numeric" placeholder="e.g. 22"></div><button class="btn quiet" id="pu-save" style="align-self:end">Log</button></div>'; }
  else if(p.kind==="sim") h+='<div class="sim-prep"><b>Sim day.</b> Eat something small an hour out. Bags 1.25 m apart, mark 20 m and 40 m. Warm up below, then run the sim. Two minutes between stations.</div>';
  h+='</div></section>';
  if(p.blocks.length){ var groups={warm:[],main:[],cool:[]}; p.blocks.forEach(function(b,i){ groups[b.warm?"warm":b.cool?"cool":"main"].push(i); });
    var li=function(i){ var b=p.blocks[i]; var id="b"+i; var c=!!dn[id]; var det= b.k==="set"? b.sets+" × "+b.reps : b.k==="int"? b.det : (b.sets?b.sets+" × ":"")+(b.sec>=60?Math.round(b.sec/60*10)/10+" min":b.sec+" s"); var rest= b.k==="int"?"":(b.rest?' <span class="rest">· rest '+b.rest+' s</span>':'');
      return '<li class="'+(c?"done":"")+'"><input type="checkbox" data-done="'+id+'" id="'+id+'"'+(c?" checked":"")+'><label for="'+id+'"><span class="n">'+esc(b.name)+'</span><span class="d">'+esc(det)+rest+'</span></label><div class="acts2">'+(b.ex&&EX[b.ex]?'<button class="qbtn" data-how="'+i+'" aria-label="How to">?</button>':'')+'<button class="play" data-play="'+i+'" aria-label="Run this exercise"><svg viewBox="0 0 24 24"><path d="M7 4l13 8-13 8z"/></svg></button></div>'+(b.ex?howHtml(b.ex):'')+'</li>'; };
    var done=function(ids){ return ids.filter(function(i){return dn["b"+i];}).length; };
    h+='<section class="block">';
    if(groups.warm.length) h+='<details class="fold"'+(S.set.foldWarm?'':' open')+'><summary>Warm-up <span class="k">'+done(groups.warm)+'/'+groups.warm.length+'</span></summary><div class="body"><ul class="ex">'+groups.warm.map(li).join("")+'</ul></div></details>';
    if(groups.main.length) h+='<div class="eyebrow" style="margin:4px 0 -2px">Work · '+done(groups.main)+'/'+groups.main.length+'</div><ul class="ex">'+groups.main.map(li).join("")+'</ul>';
    if(groups.cool.length) h+='<details class="fold"><summary>Cool-down <span class="k">'+done(groups.cool)+'/'+groups.cool.length+'</span></summary><div class="body"><ul class="ex">'+groups.cool.map(li).join("")+'</ul></div></details>';
    h+='</section>'; }
  if(p.note) h+='<div class="note">'+p.note+'</div>';
  if(!secured){ var cta= p.kind==="sim"?'<button class="btn big" id="go-test">Run the test sim</button>':'<button class="btn big" id="go-wo">'+(p.kind==="rest"?"Easy spin (optional)":"Start evolution")+'</button>'; h+='<div class="cta">'+cta+'</div>'; }
  return h; }
function howHtml(id){ var g=EX[id]; if(!g) return ""; return '<div class="how"><ul>'+g.c.map(function(c){return '<li>'+esc(c)+'</li>';}).join("")+'</ul>'+(g.m?'<div class="mis"><b>Watch for:</b> '+esc(g.m)+'</div>':'')+'<div><a href="https://www.youtube.com/results?search_query='+encodeURIComponent(g.q)+'" target="_blank" rel="noopener">Watch a demo ↗</a></div></div>'; }
function bindSessionCard(el,t,k,p){
  el.querySelectorAll("input[data-done]").forEach(function(c){ c.addEventListener("change",function(){ S.done[k]=S.done[k]||{}; S.done[k][c.dataset.done]=c.checked; save(); c.closest("li").classList.toggle("done",c.checked); if(dayComplete(t)&&!S.workouts[k]){ S.workouts[k]={sec:0,kind:p.kind,at:hhmm()}; save(); logEvent("secured","secured "+p.title); toast("Evolution secured. Streak "+trainStreak()); render(cur); } }); });
  el.querySelectorAll("[data-play]").forEach(function(b){ b.addEventListener("click",function(e){ e.preventDefault(); var i=+b.dataset.play; startWorkout({kind:p.kind,title:p.blocks[i].name,blocks:[p.blocks[i]],single:true,idx:i},k); }); });
  el.querySelectorAll("[data-how]").forEach(function(b){ b.addEventListener("click",function(e){ e.preventDefault(); e.stopPropagation(); b.closest("li").classList.toggle("open"); }); });
  el.querySelectorAll("[data-rate]").forEach(function(b){ b.addEventListener("click",function(){ var m=rate(p.kind,k,+b.dataset.rate); toast(m||"Noted."); render(cur); }); });
  var pu=el.querySelector("#pu-save"); if(pu) pu.addEventListener("click",function(){ var v=parseInt(el.querySelector("#pu").value,10); if(!v) return; var best=(S.pr.pushups||[]).reduce(function(m,x){return Math.max(m,x.n);},0); S.pr.pushups.push({date:k,n:v}); save(); if(v>best){ logEvent("pr","new push-up max: "+v); toast("Push-up PR: "+v); } else toast("Logged "+v); render(cur); });
  var g=el.querySelector("#go-wo"); if(g) g.addEventListener("click",function(){ startWorkout(planFor(t),k); });
  var gt=el.querySelector("#go-test"); if(gt) gt.addEventListener("click",function(){ startTestMode(); });
}
function renderToday(){ var t=today(), k=iso(t), p=planFor(t), w=weekOf(t); var el=$("v-today"); var h='';
  h+='<div class="hero slim"><div><div class="eyebrow">'+DAYS[t.getDay()]+' '+MON[t.getMonth()]+' '+t.getDate()+' · week '+w+'</div></div><span class="pill">'+trainStreak()+' day streak</span></div>';
  if(S.set.line) h+='<div class="line">'+esc(lineOf(t))+'</div>';
  if(isEvening()){ var tom=new Date(t); tom.setDate(t.getDate()+1); var tk=iso(tom); var ev=S.evening[tk]||{}; var pt=planFor(tom); var bt=S.bedtime.split(":"); var bed=new Date(); bed.setHours(+bt[0],+bt[1],0,0); var mins=Math.round((bed-new Date())/60000); var EVL=eveningList();
    h+='<section class="card hi stack"><div class="row"><div><div class="eyebrow">Tonight</div><h2>Set up tomorrow</h2></div><div style="text-align:right"><div class="cd">'+(mins>0?Math.floor(mins/60)+":"+("0"+mins%60).slice(-2):"now")+'</div><div class="sub">to lights out '+esc(S.bedtime)+'</div></div></div><div class="sub">Tomorrow: <b>'+esc(pt.title)+'</b>'+(pt.mins?' · ~'+pt.mins+' min':'')+'</div><ul class="ex">'+EVL.map(function(r,i){ var id="e"+i; var c=!!ev[id]; return '<li class="'+(c?"done":"")+'"><input type="checkbox" data-ev="'+id+'" id="'+id+'"'+(c?" checked":"")+'><label for="'+id+'"><span class="n">'+esc(r)+'</span></label></li>'; }).join("")+'</ul></section>'; }
  h+=sessionCard(t,k,p);
  var rt=S.routine[k]||{}; var RL=routineList(); var rc=0; for(var i=0;i<RL.length;i++) if(rt["r"+i]) rc++;
  h+='<section class="card stack"><div class="rl"><div><div class="eyebrow">Morning routine</div><h2 style="font-size:1.3rem">'+(rc===RL.length?"Locked in.":rc+" of "+RL.length)+'</h2></div>'+ring(rc/RL.length)+'</div><ul class="ex">'+RL.map(function(r,i){ var id="r"+i; var c=!!rt[id]; return '<li class="'+(c?"done":"")+'"><input type="checkbox" data-rt="'+id+'" id="'+id+'"'+(c?" checked":"")+'><label for="'+id+'"><span class="n">'+esc(r)+'</span></label></li>'; }).join("")+'</ul></section>';
  h+='<details class="fold"><summary>Note for today</summary><div class="body"><textarea id="note" placeholder="How it felt. Anything that hurt. What to change.">'+esc(S.notes[k]||"")+'</textarea></div></details>';
  el.innerHTML=h; bindSessionCard(el,t,k,p); animate(el);
  el.querySelectorAll("input[data-rt]").forEach(function(c){ c.addEventListener("change",function(){ S.routine[k]=S.routine[k]||{}; S.routine[k][c.dataset.rt]=c.checked; save(); if(routineComplete(t)) logEvent("routine","locked in the morning routine"); renderToday(); }); });
  el.querySelectorAll("input[data-ev]").forEach(function(c){ c.addEventListener("change",function(){ var tom=new Date(t); tom.setDate(t.getDate()+1); var tk=iso(tom); S.evening[tk]=S.evening[tk]||{}; S.evening[tk][c.dataset.ev]=c.checked; save(); c.closest("li").classList.toggle("done",c.checked); }); });
  var nt=el.querySelector("#note"); nt.addEventListener("input",function(){ S.notes[k]=nt.value; save(); });
}
function renderHome(){ var t=today(), k=iso(t), w=weekOf(t), p=planFor(t); var name=(S.program&&S.program.name)||""; var el=$("v-home"); var h=''; var dout=daysOut(); var secured=!!S.workouts[k];
  var mon=mondayOf(t); var sched=0,done=0; for(var i=0;i<7;i++){ var d=new Date(mon); d.setDate(mon.getDate()+i); if(planFor(d).kind!=="rest"){ sched++; if(d<=t&&dayComplete(d)) done++; } }
  var st=trainStreak();
  h+='<div class="hero slim"><div><div class="eyebrow">'+esc(greeting())+(name?", "+esc(name.split(" ")[0]):"")+'</div><div class="sub">'+DAYS[t.getDay()]+' '+MON[t.getMonth()]+' '+t.getDate()+' · week '+w+' · '+esc(PHASES[phase(w)-1].n)+'</div></div><div class="avatar sm">'+esc((name||"E").trim().charAt(0).toUpperCase())+'</div></div>';
  h+='<section class="strip"><div class="big"><div class="num" data-count="'+st+'">0</div><div class="lbl">day streak</div><div class="sub">'+(st>=14?"The clock has shifted.":st>=7?"A full week. Keep stacking.":st>0?"Don\'t break it.":"Starts today.")+'</div></div>'+bigRing(sched?done/sched:0,96,done+'<em>/'+sched+'</em>',"this week")+'</section>';
  h+='<div class="wk strip-row">'+[1,2,3,4,5,6,0].map(function(dd){ var d=new Date(mon); d.setDate(mon.getDate()+(dd===0?6:dd-1)); var pp=planFor(d); var past=d<t, isT=iso(d)===iso(t); var s= pp.kind==="rest"?"off":(past||isT)&&dayComplete(d)?"y":past?"miss":"up"; return '<div class="wd '+s+(isT?" t":"")+'"><b>'+DSHORT[dd].charAt(0)+'</b><span>'+(s==="y"?"✓":s==="miss"?"✗":s==="off"?"—":"")+'</span></div>'; }).join("")+'</div>';
  // mission card (tap → Today)
  var parts=p.title.split(" · "); var mainN=p.blocks.filter(function(b){return !b.warm&&!b.cool;}).length;
  h+='<button class="mission tap'+(secured?" secured":"")+'" id="h-mission"><div class="topo"></div><div class="mhead"><div class="eyebrow">Evolution '+("00"+(secured?evoNumber()-1:evoNumber())).slice(-3)+' · '+(secured?"secured":"today")+'</div><h1 class="mtitle">'+esc(parts[0])+(parts[1]?'<small>'+esc(parts[1])+'</small>':'')+'</h1><div class="meta">'+(p.mins?'<span>'+p.mins+' min</span>':'')+(mainN?'<span>'+mainN+' exercises</span>':'')+(secured?'<span class="hl">done '+esc(S.workouts[k].at||"")+'</span>':'')+'</div><div class="go">'+(secured?"Review":p.kind==="rest"?"Day off":"Start")+' ›</div></div></button>';
  if(t.getDay()===0) h+=weekReview(t);
  if(tpl()==="force") h+='<section class="strip two"><div><div class="num sm" data-count="'+(dout>0?dout:0)+'">0</div><div class="lbl">days to test</div></div><div><div class="num sm" data-count="'+routineStreak()+'">0</div><div class="lbl">routine streak</div></div><button class="btn quiet" id="h-test">Standards &amp; sim</button></section>';
  else h+='<section class="strip two"><div><div class="num sm" data-count="'+Object.keys(S.workouts).length+'">0</div><div class="lbl">secured</div></div><div><div class="num sm" data-count="'+routineStreak()+'">0</div><div class="lbl">routine streak</div></div></section>';
  h+='<section class="card stack" id="h-chal"><div class="eyebrow">Challenges</div>'+(CU?'<div class="skel"></div><div class="skel short"></div>':'<div class="sub">Sign in on the Crew tab.</div>')+'</section>';
  h+='<section class="card stack" id="h-feed"><div class="eyebrow">Crew</div>'+(CU?'<div class="skel"></div><div class="skel"></div><div class="skel short"></div>':'<div class="sub">Your crew\'s activity shows up here.</div>')+'</section>';
  var pu=S.pr.pushups||[]; var puBest=pu.length?Math.max.apply(null,pu.map(function(x){return x.n;})):null; var sims=S.sims.slice().sort(function(a,b){return a.date<b.date?-1:1;}); var best=function(key){ var v=sims.map(function(s){return secs(s[key]);}).filter(function(x){return x!==null;}); return v.length?Math.min.apply(null,v):null; };
  h+='<section><div class="eyebrow" style="margin-bottom:8px">Personal bests</div><div class="prs"><div class="prc"><b>'+(puBest!==null?puBest:"—")+'</b><span>push-ups</span></div><div class="prc"><b>'+longestStreak()+'</b><span>best streak</span></div>'+(tpl()==="force"?'<div class="prc"><b>'+mmss(best("rush"))+'</b><span>rushes · 0:51</span></div><div class="prc"><b>'+mmss(best("lift"))+'</b><span>lift · 3:30</span></div><div class="prc"><b>'+mmss(best("shut"))+'</b><span>shuttles · 5:21</span></div>':'')+'</div></section>';
  h+='<section class="card stack"><div class="eyebrow">Last 8 weeks</div><div class="dow">'+DSHORT.slice(1).concat(DSHORT[0]).map(function(x){return "<div>"+x+"</div>";}).join("")+'</div><div class="heat">'; var m8=mondayOf(t); m8.setDate(m8.getDate()-49); for(var j=0;j<56;j++){ var d2=new Date(m8); d2.setDate(m8.getDate()+j); var cls=""; var fut=d2>t; if(planFor(d2).kind==="rest") cls="r"; else if(!fut&&dayComplete(d2)) cls="y"; if(iso(d2)===iso(t)) cls+=" t"; if(fut||d2<fromIso(S.start)) cls+=" f"; h+='<div class="'+cls+'"></div>'; } h+='</div></section>';
  el.innerHTML=h; animate(el); el.querySelector("#h-mission").addEventListener("click",function(){ show("today"); }); var ht=el.querySelector("#h-test"); if(ht) ht.addEventListener("click",function(){ show("test"); }); if(CU) loadHomeSocial();
}
function evoNumber(){ return Object.keys(S.workouts).length+1; }
function greeting(){ var h=new Date().getHours(); return h<5?"Early.":h<12?"Good morning":h<17?"Afternoon":"Evening"; }
function bigRing(p,size,label,sub){ var r=(size/2)-8, c=2*Math.PI*r; return '<div class="bigring" style="width:'+size+'px;height:'+size+'px"><svg viewBox="0 0 '+size+' '+size+'"><circle class="bgc" cx="'+size/2+'" cy="'+size/2+'" r="'+r+'"/><circle class="fgc" cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" stroke-dasharray="'+c+'" stroke-dashoffset="'+c+'" data-to="'+(c*(1-p))+'"/></svg><div class="in"><b>'+label+'</b><span>'+sub+'</span></div></div>'; }
function animate(el){ if(!el) return; var reduce=false; try{ reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches; }catch(e){}
  el.querySelectorAll("[data-count]").forEach(function(n){ var to=+n.dataset.count; if(reduce||!to){ n.textContent=to; return; } var t0=null; var dur=700; var step=function(ts){ if(!t0) t0=ts; var p=Math.min(1,(ts-t0)/dur); p=1-Math.pow(1-p,3); n.textContent=Math.round(to*p); if(p<1) requestAnimationFrame(step); }; requestAnimationFrame(step); });
  el.querySelectorAll(".fgc[data-to]").forEach(function(c){ var to=c.dataset.to; if(reduce){ c.style.transition="none"; } requestAnimationFrame(function(){ requestAnimationFrame(function(){ c.style.strokeDashoffset=to; }); }); });
  if(!reduce) el.querySelectorAll(".view > *").forEach(function(x,i){ x.classList.add("in"); x.style.animationDelay=(Math.min(i,8)*45)+"ms"; }); }
function ring(p){ var r=22, c=2*Math.PI*r; return '<svg class="ring" viewBox="0 0 54 54"><circle class="bgc" cx="27" cy="27" r="'+r+'"/><circle class="fgc" cx="27" cy="27" r="'+r+'" stroke-dasharray="'+c+'" stroke-dashoffset="'+(c*(1-p))+'"/></svg>'; }
function weekReview(t){ var mon=new Date(t); mon.setDate(t.getDate()-6); var done=0,rd=0,sched=0; for(var i=0;i<7;i++){ var d=new Date(mon); d.setDate(mon.getDate()+i); if(planFor(d).kind!=="rest"){ sched++; if(dayComplete(d)) done++; } if(routineComplete(d)) rd++; }
  var w=weekOf(t); var grade= done>=sched?"Clean week.":done>=sched-1?"Solid. One slipped.":done>=sched-2?"Two missed. Fix them before they become the pattern.":"The routine's the problem, not the program.";
  return '<div class="card stack" style="border-color:var(--accent)"><div class="eyebrow">Week '+w+' review</div><h2>'+esc(grade)+'</h2><div class="stats"><div class="stat"><div class="v">'+done+'/'+sched+'</div><div class="l">Evolutions</div></div><div class="stat"><div class="v">'+rd+'/7</div><div class="l">Routine</div></div><div class="stat"><div class="v">'+longestStreak()+'</div><div class="l">Best streak</div></div></div></div>'; }

// ================= WORKOUT ENGINE =================
var W=null, W_last="";
function expand(plan){ var steps=[]; plan.blocks.forEach(function(b,bi){ var ex=b.ex;
  if(b.k==="set"){ for(var s=1;s<=b.sets;s++){ steps.push({t:"work",name:b.name,det:b.det,sub:"Set "+s+" of "+b.sets+" · "+b.reps,b:bi,manual:true,ex:ex}); if(s<b.sets&&b.rest) steps.push({t:"rest",name:"Rest",det:"Next: "+b.name+" set "+(s+1),sec:b.rest,b:bi}); } }
  else if(b.k==="dur"&&b.sets){ for(var s2=1;s2<=b.sets;s2++){ steps.push({t:"work",name:b.name,det:b.det,sub:"Set "+s2+" of "+b.sets,sec:b.sec,b:bi,ex:ex}); if(s2<b.sets&&b.rest) steps.push({t:"rest",name:"Rest",det:"Next: "+b.name+" set "+(s2+1),sec:b.rest,b:bi}); } }
  else if(b.k==="dur"){ steps.push({t:"work",name:b.name,det:b.det,sub:"",sec:b.sec,b:bi,easy:true,ex:ex}); }
  else if(b.k==="int"){ for(var r=1;r<=b.rounds;r++){ steps.push({t:"work",name:"HARD",det:"Round "+r+" of "+b.rounds,sub:"",sec:b.work,b:bi}); steps.push({t:"rest",name:"EASY",det:r<b.rounds?"Round "+(r+1)+" is next":"Last one.",sec:b.rest,b:bi}); } } }); return steps; }
function startWorkout(plan,k){ var steps=expand(plan); if(!steps.length) return; W={plan:plan,k:k,steps:steps,i:0,t0:Date.now(),stepStart:Date.now(),paused:false,pausedAt:0,tick:null,lastBeep:-1}; beep(880,80,0.001); wake(true); $("wo").hidden=false; document.body.style.overflow="hidden"; $("fab").hidden=true; W.tick=setInterval(woTick,100); woRender(); }
function stepElapsed(){ return (W.paused?W.pausedAt:Date.now())-W.stepStart; }
function woTick(){ if(!W||W.paused) return; var st=W.steps[W.i]; if(st.sec){ var left=st.sec*1000-stepElapsed(); var s=Math.ceil(left/1000); if(s<=3&&s>=1&&s!==W.lastBeep){ W.lastBeep=s; beep(660,90); buzz(40); } if(left<=0){ beep(st.t==="rest"?1046:523,350,0.35); buzz([60,40,60]); next(); return; } var b=$("wo-big"); if(b) b.textContent=mmss(Math.max(0,s)); } else { var b2=$("wo-big"); if(b2) b2.textContent=mmss(Math.floor(stepElapsed()/1000)); } var tot=$("wo-tot"); if(tot) tot.textContent=mmss(Math.floor((Date.now()-W.t0)/1000)); }
function next(){ W.i++; W.stepStart=Date.now(); W.lastBeep=-1; if(W.i>=W.steps.length){ finish(); return; } woRender(); }
function prev(){ if(W.i>0){ W.i--; W.stepStart=Date.now(); W.lastBeep=-1; woRender(); } }
function woRender(){ var st=W.steps[W.i]; var el=$("wo"); var nx=W.steps[W.i+1];
  var h='<div class="top"><div><div class="eyebrow">'+esc(W.plan.title)+'</div><div class="cnt">Step '+(W.i+1)+' / '+W.steps.length+' · <span id="wo-tot">0:00</span></div></div><button class="btn quiet" id="wo-x" style="padding:8px 12px">Exit</button></div><div class="prog"><i style="width:'+Math.round(W.i/W.steps.length*100)+'%"></i></div>';
  h+='<div class="mid"><div class="phase '+(st.t==="rest"?"rest":"work")+'">'+(st.t==="rest"?"Rest":st.easy?"Go":"Work")+'</div><div class="name">'+esc(st.name)+'</div>'+(st.sub?'<div class="det" style="color:var(--fg);font-weight:600">'+esc(st.sub)+'</div>':'')+(st.det?'<div class="det">'+esc(st.det)+'</div>':'');
  var g=st.ex&&EX[st.ex]; if(st.t==="work"&&g) h+='<div class="cues"><ul>'+g.c.slice(0,3).map(function(c){return '<li>'+esc(c)+'</li>';}).join("")+'</ul></div>';
  h+='<div class="big '+(st.t==="rest"?"rest":"")+'" id="wo-big">'+(st.sec?mmss(st.sec):"0:00")+'</div>'+(!st.sec?'<div class="cnt">Tap done when the set is finished</div>':'')+'</div><div class="acts">';
  h+= st.manual?'<button class="btn big" id="wo-done">Set done</button>':'<button class="btn big '+(st.t==="rest"?"quiet":"")+'" id="wo-skip">'+(st.t==="rest"?"Skip rest":"Skip")+'</button>';
  h+='<div class="row" style="justify-content:space-between"><button class="btn quiet" id="wo-prev" style="flex:1">Back</button><button class="btn quiet" id="wo-pause" style="flex:1">'+(W.paused?"Resume":"Pause")+'</button></div><div class="next">'+(nx?"Next: "+esc(nx.name)+(nx.sub?" · "+esc(nx.sub):"")+(nx.sec?" · "+mmss(nx.sec):""):"Last step")+'</div></div>';
  el.innerHTML=h; var q=function(id){return el.querySelector("#"+id);};
  q("wo-x").addEventListener("click",function(){ if(el.querySelector("#wo-confirm")) return; var c=document.createElement("div"); c.id="wo-confirm"; c.className="note"; c.innerHTML='<b>Exit without finishing?</b> <div class="row" style="margin-top:8px"><button class="btn danger" id="wo-yes" style="flex:1">Exit</button><button class="btn quiet" id="wo-no" style="flex:1">Keep going</button></div>'; el.querySelector(".acts").appendChild(c); c.querySelector("#wo-yes").addEventListener("click",closeWo); c.querySelector("#wo-no").addEventListener("click",function(){ c.remove(); }); });
  if(q("wo-done")) q("wo-done").addEventListener("click",function(){ beep(523,120); next(); }); if(q("wo-skip")) q("wo-skip").addEventListener("click",next); q("wo-prev").addEventListener("click",prev);
  q("wo-pause").addEventListener("click",function(){ if(W.paused){ var pd=Date.now()-W.pausedAt; W.stepStart+=pd; W.t0+=pd; W.paused=false; } else { W.paused=true; W.pausedAt=Date.now(); } woRender(); }); }
function closeWo(){ if(W){ W_last=W.plan.title; if(W.tick) clearInterval(W.tick);} W=null; wake(false); $("wo").hidden=true; document.body.style.overflow=""; $("fab").hidden=false; render(cur); }
function finish(){ var sec=Math.round((Date.now()-W.t0)/1000); var k=W.k; var kind=W.plan.kind; var t=today();
  if(W.plan.single){ S.done[k]=S.done[k]||{}; S.done[k]["b"+W.plan.idx]=true; save(); beep(784,150,0.3); buzz([80,50,80]); if(dayComplete(t)&&!S.workouts[k]){ S.workouts[k]={sec:0,kind:kind,at:hhmm()}; save(); logEvent("secured","secured "+planFor(t).title); } closeWo(); toast("Done"); return; }
  S.workouts[k]={sec:sec,kind:kind,at:hhmm()}; S.done[k]=S.done[k]||{}; W.plan.blocks.forEach(function(b,i){ S.done[k]["b"+i]=true; }); save(); logEvent("secured","secured "+W.plan.title+" in "+mmss(sec));
  beep(784,150,0.3); setTimeout(function(){beep(1046,300,0.3);},160); buzz([80,50,80,50,160]);
  var el=$("wo"); var s=trainStreak(); var generated=(S.plan.days[t.getDay()]||{}).type!=="custom"; var adaptive=(kind==="lift"||kind==="bike")&&generated;
  el.innerHTML='<div class="top"><div class="eyebrow">'+esc(W.plan.title)+'</div></div><div class="mid"><div class="done-wrap pop"><div class="phase work">Evolution secured</div><div class="huge">'+mmss(sec)+'</div><div class="sub">on the clock</div><div class="stats" style="width:100%;max-width:360px"><div class="stat"><div class="v">'+s+'</div><div class="l">Day streak</div></div><div class="stat"><div class="v">'+Object.keys(S.workouts).length+'</div><div class="l">Secured</div></div><div class="stat"><div class="v">'+(tpl()==="force"?daysOut():longestStreak())+'</div><div class="l">'+(tpl()==="force"?"Days out":"Best streak")+'</div></div></div>'+(adaptive?'<div class="stack" style="width:100%;max-width:360px"><div class="eyebrow">How was it?</div><div class="rate"><button class="btn quiet" data-rate="1">Easy</button><button class="btn quiet" data-rate="2">Right</button><button class="btn quiet" data-rate="3">Too hard</button></div><div class="sub" id="rate-msg" style="min-height:1.4em"></div></div>':'<div class="sub" style="max-width:32ch">'+esc(doneLine(s))+'</div>')+'</div></div><div class="acts"><button class="btn big" id="wo-close">Secure</button></div>';
  el.querySelectorAll("[data-rate]").forEach(function(b){ b.addEventListener("click",function(){ el.querySelectorAll("[data-rate]").forEach(function(x){x.classList.remove("sel");}); b.classList.add("sel"); var m=rate(kind,k,+b.dataset.rate); el.querySelector("#rate-msg").textContent=m||doneLine(s); }); });
  el.querySelector("#wo-close").addEventListener("click",closeWo); if(W.tick) clearInterval(W.tick); W.tick=null; }
