  h+='<div class="sub">'+ids.length+' of '+Object.keys(EX).length+'</div><ul class="ex">'+ids.map(function(id){ var e=EX[id]; var kn=function(k){ var n=KIT.filter(function(x){return x[0]===k;})[0]; return n?n[1]:k; }; var need=(e.req&&e.req.length)?e.req.map(kn).join(" + "):e.eq.length?e.eq.map(kn).join(" or "):"No kit"; var def=e.t==="int"?e.rounds+" × "+e.work+"/"+e.rest+" s":e.t==="dur"?(e.sets?e.sets+" × ":"")+e.sec+" s":e.sets+" × "+e.reps;
    return '<li class="'+(canDo(id)?"":"cant")+'"><span></span><label><span class="n">'+esc(e.n)+'</span><span class="d">'+esc(def)+' · '+esc(need)+'</span><button class="howbtn" data-how="'+id+'">How do I do this?</button></label>'+(picking?'<button class="play" data-pick="'+id+'" aria-label="Add"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="3" fill="none"/></svg></button>':'<span></span>')+howHtml(id)+'</li>'; }).join("")+'</ul>';
  el.innerHTML=h;
