  el.querySelectorAll("[data-cat]").forEach(function(b){ b.addEventListener("click",function(){ LIB.cat=b.dataset.cat; renderLibrary(arg); }); });
  el.querySelector("#lib-mine").addEventListener("change",function(e){ LIB.mine=e.target.checked; renderLibrary(arg); });
