  var hist=Object.keys(S.workouts).sort().reverse().slice(0,10); h+='<div class="card stack"><div class="eyebrow">History</div>'+(hist.length?'<div class="hist">'+hist.map(function(k){ var wk=S.workouts[k]; var d=fromIso(k); return '<div class="hrow"><span>'+DSHORT[d.getDay()]+' '+MON[d.getMonth()]+' '+d.getDate()+'</span><span class="sub">'+esc(planFor(d).title)+'</span><span class="mono">'+(wk.sec?mmss(wk.sec):"✓")+'</span></div>'; }).join("")+'</div>':'<div class="sub">Nothing yet.</div>')+'</div>';
