function openQt(){ Q=Q||{mode:"idle",t0:0,acc:0,len:0,tick:null,lastBeep:-1}; $("qt").hidden=false; document.body.style.overflow="hidden"; wake(true); qtRender(); }
function closeQt(){ if(Q&&Q.tick) clearInterval(Q.tick); Q=null; $("qt").hidden=true; document.body.style.overflow=""; wake(false); }
function qtStart(len){ if(Q.tick) clearInterval(Q.tick); Q.len=len; Q.acc=0; Q.t0=Date.now(); Q.mode="run"; Q.lastBeep=-1; Q.tick=setInterval(qtTick,100); qtRender(); }
function qtTick(){ if(!Q||Q.mode!=="run") return; var el=$("qt-big"); var e=Q.acc+Date.now()-Q.t0; if(Q.len){ var left=Q.len*1000-e; var s=Math.ceil(left/1000); if(s<=3&&s>=1&&s!==Q.lastBeep){ Q.lastBeep=s; beep(660,90); buzz(40);} if(left<=0){ beep(1046,400,0.35); buzz([80,50,80,50,160]); Q.mode="done"; clearInterval(Q.tick); qtRender(); return; } if(el) el.textContent=mmss(Math.max(0,s)); } else if(el) el.textContent=mmss1(e); }
function qtRender(){ var el=$("qt"); var running=Q.mode==="run"; var h='<div class="row"><div class="eyebrow">Timer</div><button class="btn quiet" id="qt-x" style="padding:8px 12px">Close</button></div><div class="mid"><div class="eyebrow">'+(Q.mode==="done"?"Time":Q.len?"Countdown":Q.mode==="run"?"Stopwatch":"Pick one")+'</div><div class="big" id="qt-big">'+(Q.len?mmss(Q.len):"0:00.0")+'</div><div class="presets">'+[30,45,60,90].map(function(n){return '<button class="btn '+(Q.len===n&&running?"":"quiet")+'" data-qt="'+n+'">'+n+' s</button>';}).join("")+'<button class="btn quiet" data-qt="120">2 min</button><button class="btn quiet" data-qt="180">3 min</button><button class="btn quiet" data-qt="300">5 min</button><button class="btn quiet" data-qt="0">Stopwatch</button></div><div class="row" style="width:100%;max-width:420px"><button class="btn big" id="qt-stop" style="flex:1" '+(running?"":"disabled")+'>Stop</button></div></div>'; el.innerHTML=h;
  el.querySelector("#qt-x").addEventListener("click",closeQt); el.querySelectorAll("[data-qt]").forEach(function(b){ b.addEventListener("click",function(){ qtStart(+b.dataset.qt); }); });
  el.querySelector("#qt-stop").addEventListener("click",function(){ if(Q.tick) clearInterval(Q.tick); Q.acc+=Date.now()-Q.t0; Q.mode="idle"; qtRender(); var big=el.querySelector("#qt-big"); if(big) big.textContent=Q.len?mmss(Math.max(0,Math.ceil((Q.len*1000-Q.acc)/1000))):mmss1(Q.acc); }); }

